import 'dart:convert';import 'package:http/http.dart' as http;import '../config.dart';class Api{Future<Map<String,dynamic>>post(String p,Map<String,dynamic>b)async{final r=await http.post(Uri.parse('$apiBaseUrl$p'),headers:{'Content-Type':'application/json'},body:jsonEncode(b));final d=jsonDecode(r.body);if(r.statusCode>=400)throw Exception(d['message']??'Gagal');return d;}Future<Map<String,dynamic>>put(String p,Map<String,dynamic>b)async{final r=await http.put(Uri.parse('$apiBaseUrl$p'),headers:{'Content-Type':'application/json'},body:jsonEncode(b));return jsonDecode(r.body);}}